const effects = [];
function decide(a, b, c) {
  if ((effects.push(`a:${a}`), a) && (effects.push(`b:${b}`), b) || (effects.push(`c:${c}`), c)) return 'yes';
  return 'no';
}
function run() {
  return [[false,false,false],[false,false,true],[true,false,false],[true,false,true],[true,true,false],[true,true,true]].map((args) => decide(...args));
}
function observe() { return effects; }

const effects = [];
const receiver = {
  get left() { effects.push('left'); return 1; },
  get right() { effects.push('right'); return 0; },
  decide() {
    if (this.left && this.right) return 'both';
    return 'not-both';
  }
};
function run() { return receiver.decide(); }
function observe() { return effects; }

const effects = [];
function descend(depth) {
  if ((effects.push(`depth:${depth}`), depth > 0) && descend(depth - 1)) return depth < 3;
  return depth === 0;
}
function run() { return descend(4); }
function observe() { return effects; }

const effects = [];
function decide(a, b, c) {
  if (!(a || (effects.push('b'), b)) && (effects.push('c'), c)) return 1;
  return 0;
}
function run() { return [decide(false, false, true), decide(false, true, true), decide(true, false, true)]; }
function observe() { return effects; }

const effects = [];
function decide(a, b) {
  return (effects.push(`a:${a}`), a) && (effects.push(`b:${b}`), b) ? 'yes' : 'no';
}
function run() { return [decide(false, false), decide(true, false), decide(true, true)]; }
function observe() { return effects; }

const effects = [];
function run() {
  let index = 0;
  let total = 0;
  while ((effects.push(`test:${index}`), index < 3) && total < 6) { total += ++index; }
  return { index, total };
}
function observe() { return effects; }

const effects = [];
function run() {
  let index = 0;
  let total = 0;
  do { total += index; index++; } while ((effects.push(`test:${index}`), index < 3) || total < 1);
  return { index, total };
}
function observe() { return effects; }

const effects = [];
function run() {
  let total = 0;
  for (let index = 0; (effects.push(`test:${index}`), index < 3) && total < 6; index++) { total += index + 1; }
  return total;
}
function observe() { return effects; }
